package com.greenocean.backend.professional.service;

import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.identity.AccessPolicy;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Value;
import java.time.*;
import java.util.*;
import static com.greenocean.backend.professional.service.ProfessionalAuthority.time;

@Service @Transactional
public class ClinicCommerce {
    private final JdbcTemplate db;
    private final ProfessionalAuthority authority;
    private final GrowthLibrary roles;
    private final AccessPolicy access;
    private final List<ClinicPaymentProvider> providers;
    private final boolean enabled;
    public ClinicCommerce(JdbcTemplate db, ProfessionalAuthority authority, GrowthLibrary roles, AccessPolicy access,
            List<ClinicPaymentProvider> providers, @Value("${greenocean.clinic.commerce-enabled:false}") boolean enabled) {
        this.db=db;this.authority=authority;this.roles=roles;this.access=access;this.providers=providers;this.enabled=enabled;
    }
    public record Policy(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=80) String version,
        @jakarta.validation.constraints.Min(0) @jakarta.validation.constraints.Max(10000) int commissionBps,
        @jakarta.validation.constraints.Min(0) @jakarta.validation.constraints.Max(1000000000) long providerFeeUnits,
        @jakarta.validation.constraints.Size(min=10,max=5000) @jakarta.validation.constraints.NotBlank String terms,
        @jakarta.validation.constraints.Size(min=10,max=5000) @jakarta.validation.constraints.NotBlank String refundPolicy) {}
    public record Booking(@jakarta.validation.constraints.NotNull UUID slotId,@jakarta.validation.constraints.NotNull UUID retryKey,
        @jakarta.validation.constraints.Min(1) long slotRevision,@jakarta.validation.constraints.NotNull UUID policyId,
        @jakarta.validation.constraints.Min(0) long expectedUnits, boolean confirmed) {}
    public record Change(@jakarta.validation.constraints.Min(1) long revision,@jakarta.validation.constraints.NotBlank String action,
        @jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(min=3,max=2000) String reason) {}
    private void finance(UUID who){if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.id=? AND u.status='ACTIVE' AND r.name IN('ADMIN','CLINIC_FINANCE'))",Boolean.class,who)))throw new ForbiddenException("Current financial operations authority is required");}
    private void enabled(){if(!enabled)throw new ForbiddenException("Clinic booking/financial purpose and retention approval is required");}
    private void patientLock(UUID id){db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","clinic-patient:"+id);}
    public UUID policy(UUID actor,Policy p){roles.admin(actor);ProfessionalAuthority.text(p.terms(),5000);ProfessionalAuthority.text(p.refundPolicy(),5000);
        if(p.commissionBps()<0||p.commissionBps()>10000||p.providerFeeUnits()<0||p.providerFeeUnits()>1000000000)throw new IllegalArgumentException("Invalid integer policy");
        return db.queryForObject("INSERT INTO clinic_commercial_policies(version,commission_bps,provider_fee_units,terms,refund_policy,approved_by) VALUES(?,?,?,?,?,?) RETURNING id",UUID.class,p.version(),p.commissionBps(),p.providerFeeUnits(),p.terms(),p.refundPolicy(),actor);}
    public List<Map<String,Object>> policies(UUID actor){authority.actor(actor);return safe(db.queryForList("SELECT id,version,commission_bps,provider_fee_units,terms,refund_policy FROM clinic_commercial_policies ORDER BY created_at DESC LIMIT 100"));}
    public void offer(UUID who,UUID slot,UUID policy,boolean approval){authority.owner(who);authority.lock(who);
        if(db.queryForList("SELECT id FROM clinic_commercial_policies WHERE id=?",policy).isEmpty())throw new NotFoundException("Commercial policy was not found");
        if(db.queryForList("SELECT id FROM professional_availability_slots WHERE id=? AND professional_user_id=? AND status IN('DRAFT','AVAILABLE') FOR UPDATE",slot,who).isEmpty())throw new ConflictException("Only an unreserved own slot may accept terms");
        db.update("INSERT INTO clinic_slot_offers(slot_id,policy_id,approval_required) VALUES(?,?,?) ON CONFLICT(slot_id) DO UPDATE SET policy_id=EXCLUDED.policy_id,approval_required=EXCLUDED.approval_required,accepted_at=CURRENT_TIMESTAMP",slot,policy,approval);
        db.update("UPDATE professional_availability_slots SET revision=revision+1 WHERE id=?",slot);
        authority.audit(who,"COMMERCIAL_TERMS_ACCEPTED",slot,"Explicit professional agreement to version "+policy);}
    public List<Map<String,Object>> offers(UUID who,UUID professional){enabled();authority.actor(who);authority.offer(professional,"IR","TEXT");
        return safe(db.queryForList("SELECT s.id,s.starts_at,s.ends_at,s.consultation_mode,s.price_units,s.currency,s.revision,o.policy_id,o.approval_required,p.version,p.terms,p.refund_policy,p.commission_bps,CASE WHEN s.price_units=0 THEN 0 ELSE p.provider_fee_units END AS provider_fee_units FROM professional_availability_slots s JOIN clinic_slot_offers o ON o.slot_id=s.id JOIN clinic_commercial_policies p ON p.id=o.policy_id WHERE s.professional_user_id=? AND s.governed AND s.status='AVAILABLE' AND s.starts_at>CURRENT_TIMESTAMP+INTERVAL '15 minutes' AND professional_scope_live(s.professional_user_id,'IR',s.consultation_mode) ORDER BY s.starts_at LIMIT 100",professional));}
    public Map<String,Object> book(UUID patient,Booking in){enabled();authority.actor(patient);patientLock(patient);
        var retries=db.queryForList("SELECT * FROM consultation_requests WHERE requester_user_id=? AND booking_key=?",patient,in.retryKey());
        if(!retries.isEmpty()){var r=retries.getFirst();if(!in.slotId().equals(r.get("availability_slot_id"))||!in.policyId().equals(r.get("policy_id"))||in.expectedUnits()!=number(r,"price_units"))throw new ConflictException("Retry key is already bound to another booking");return appointment(patient,(UUID)r.get("id"));}
        var owners=db.queryForList("SELECT professional_user_id FROM professional_availability_slots WHERE id=?",in.slotId());if(owners.isEmpty())throw new NotFoundException("Availability was not found");UUID professional=(UUID)owners.getFirst().get("professional_user_id");authority.lock(professional);authority.offer(professional,"IR",mode(in.slotId()));access.requireCare(patient,professional,mode(in.slotId()));
        if(patient.equals(professional))throw new ConflictException("Self booking is not available");
        var rows=db.queryForList("SELECT s.*,o.policy_id,o.approval_required,p.commission_bps,p.provider_fee_units,p.terms,p.refund_policy,p.version FROM professional_availability_slots s JOIN clinic_slot_offers o ON o.slot_id=s.id JOIN clinic_commercial_policies p ON p.id=o.policy_id WHERE s.id=? FOR UPDATE OF s,o",in.slotId());
        if(rows.isEmpty())throw new ConflictException("An explicit professional commercial agreement is required");var s=rows.getFirst();
        if(!in.confirmed()||!"AVAILABLE".equals(s.get("status"))||!Boolean.TRUE.equals(s.get("governed"))||in.slotRevision()!=number(s,"revision")||!in.policyId().equals(s.get("policy_id"))||in.expectedUnits()!=number(s,"price_units")||((java.sql.Timestamp)s.get("starts_at")).toInstant().isBefore(Instant.now().plusSeconds(900)))throw new ConflictException("Review the current price, terms and future availability before confirming");
        if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM consultation_requests WHERE requester_user_id=? AND status IN('REQUESTED','PAYMENT_PENDING','CONFIRMED','SESSION_ACTIVE') AND scheduled_at<? AND COALESCE(ends_at,scheduled_at+INTERVAL '8 hours')>?)",Boolean.class,patient,s.get("ends_at"),s.get("starts_at"))))throw new ConflictException("Another active appointment overlaps this interval");
        long amount=number(s,"price_units"),commission=Math.multiplyExact(amount,number(s,"commission_bps"))/10000,fee=amount==0?0:number(s,"provider_fee_units");
        if(commission+fee>amount)throw new ConflictException("Configured fees exceed the agreed total");
        if(amount>0)providerGate((String)s.get("consultation_mode"));
        boolean approval=Boolean.TRUE.equals(s.get("approval_required"));String state=approval?"REQUESTED":amount>0?"PAYMENT_PENDING":"CONFIRMED";
        UUID id=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,availability_slot_id,scheduled_at,ends_at,consultation_mode,status,clinic_governed,booking_key,price_units,commission_units,provider_fee_units,currency,policy_id,terms_snapshot,confirmed_at,payment_deadline,approval_required,profession_snapshot) VALUES(?,?,?,?,?,?,?,TRUE,?,?,?,?, 'IRR',?,?,CASE WHEN ?='CONFIRMED' THEN CURRENT_TIMESTAMP END,LEAST(?::timestamptz,CURRENT_TIMESTAMP+INTERVAL '15 minutes'),?,?) RETURNING id",UUID.class,patient,professional,in.slotId(),s.get("starts_at"),s.get("ends_at"),s.get("consultation_mode"),state,in.retryKey(),amount,commission,fee,in.policyId(),s.get("version")+"\n"+s.get("terms")+"\n"+s.get("refund_policy"),state,s.get("starts_at"),approval,db.queryForObject("SELECT professional_type FROM professional_profiles WHERE user_id=?",String.class,professional));
        db.update("UPDATE professional_availability_slots SET status='BOOKED',revision=revision+1 WHERE id=?",in.slotId());
        db.update("INSERT INTO clinic_invoices(appointment_id,amount_units,currency) VALUES(?,?,'IRR')",id,amount);event(id,1,patient,state,"Explicit patient confirmation of immutable price and terms");return appointment(patient,id);}
    private String mode(UUID slot){return db.queryForObject("SELECT consultation_mode FROM professional_availability_slots WHERE id=?",String.class,slot);}
    public Map<String,Object> appointment(UUID who,UUID id){authority.actor(who);var rows=db.queryForList("SELECT id,requester_user_id,professional_user_id,availability_slot_id,scheduled_at,ends_at,consultation_mode,status,booking_revision,price_units,commission_units,provider_fee_units,currency,policy_id,terms_snapshot,confirmed_at,payment_deadline,approval_required FROM consultation_requests WHERE id=? AND clinic_governed AND(requester_user_id=? OR professional_user_id=?)",id,who,who);if(rows.isEmpty())throw new NotFoundException("Own clinic appointment was not found");var r=rows.getFirst();r.put("history",db.queryForList("SELECT revision,state,reason,created_at FROM clinic_appointment_events WHERE appointment_id=? ORDER BY revision",id));return (Map<String,Object>)ProfessionalAuthority.jsonSafe(r);}
    public List<Map<String,Object>> appointments(UUID who){authority.actor(who);return safe(db.queryForList("SELECT id,professional_user_id,requester_user_id,scheduled_at,ends_at,status,booking_revision,price_units,currency FROM consultation_requests WHERE clinic_governed AND(requester_user_id=? OR professional_user_id=?) ORDER BY scheduled_at DESC LIMIT 100",who,who));}
    private Map<String,Object> lock(UUID id){var owners=db.queryForList("SELECT professional_user_id FROM consultation_requests WHERE id=? AND clinic_governed",id);if(!owners.isEmpty())authority.lock((UUID)owners.getFirst().get("professional_user_id"));var r=db.queryForList("SELECT * FROM consultation_requests WHERE id=? AND clinic_governed FOR UPDATE",id);if(r.isEmpty())throw new NotFoundException("Clinic appointment was not found");return r.getFirst();}
    public void change(UUID who,UUID id,Change in){authority.actor(who);var c=lock(id);boolean patient=who.equals(c.get("requester_user_id")),pro=who.equals(c.get("professional_user_id"));if(!patient&&!pro)throw new NotFoundException("Own clinic appointment was not found");ProfessionalAuthority.text(in.reason(),2000);
        String old=(String)c.get("status"),next;
        if(in.action().equals("CANCEL")){next=patient?"CANCELLED_BY_PATIENT":"CANCELLED_BY_PROFESSIONAL";if(old.equals(next))return;if(!Set.of("REQUESTED","PAYMENT_PENDING","CONFIRMED").contains(old))throw new ConflictException("This appointment cannot be cancelled directly");}
        else if(in.action().equals("APPROVE")&&pro&&old.equals("REQUESTED")){authority.offer(who,"IR",(String)c.get("consultation_mode"));next=number(c,"price_units")==0?"CONFIRMED":"PAYMENT_PENDING";}
        else throw new ConflictException("Use an explicit supported appointment transition");
        if(in.revision()!=number(c,"booking_revision"))throw new ConflictException("Appointment changed; reload before acting");
        if(next.equals("PAYMENT_PENDING")&&((java.sql.Timestamp)c.get("payment_deadline")).toInstant().isBefore(Instant.now()))throw new ConflictException("Payment reservation expired; cancel and book a new slot");
        transition(c,who,next,in.reason());if(next.startsWith("CANCELLED")){db.update("UPDATE professional_availability_slots SET status='CANCELLED',revision=revision+1 WHERE id=?",c.get("availability_slot_id"));if(pro)obligation(c,in.reason());else if(captured(id))dispute(who,id,"Cancellation refund review: "+in.reason());}}
    private void transition(Map<String,Object> c,UUID actor,String state,String reason){long rev=number(c,"booking_revision")+1;db.update("UPDATE consultation_requests SET status=?,booking_revision=?,confirmed_at=CASE WHEN ?='CONFIRMED' THEN COALESCE(confirmed_at,CURRENT_TIMESTAMP) ELSE confirmed_at END WHERE id=?",state,rev,state,c.get("id"));event((UUID)c.get("id"),rev,actor,state,reason);}
    private void event(UUID id,long rev,UUID actor,String state,String reason){db.update("INSERT INTO clinic_appointment_events(appointment_id,revision,actor_id,state,reason) VALUES(?,?,?,?,?)",id,rev,actor,state,reason);}
    private ClinicPaymentProvider provider(){if(providers.size()!=1||!providers.getFirst().authorized())throw new ConflictException("An owner-approved authorized payment adapter is not configured");return providers.getFirst();}
    private void providerGate(String mode){provider();if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_release_approvals a JOIN users u ON u.id=a.approved_by WHERE a.country_code='IR' AND a.mode=? AND a.purpose='PAYMENT_PROVIDER' AND a.revoked_at IS NULL AND a.expires_at>CURRENT_TIMESTAMP AND u.status='ACTIVE' AND EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=u.id AND r.name='ADMIN'))",Boolean.class,mode)))throw new ForbiddenException("Current independent payment operating approval is required");}
    public Map<String,Object> payment(UUID who,UUID id){enabled();var c=lock(id);if(!who.equals(c.get("requester_user_id")))throw new NotFoundException("Own appointment was not found");authority.actor(who);providerGate((String)c.get("consultation_mode"));
        var existing=db.queryForList("SELECT p.* FROM clinic_payment_intents p JOIN clinic_invoices i ON i.id=p.invoice_id WHERE i.appointment_id=?",id);
        if(!"PAYMENT_PENDING".equals(c.get("status"))||((java.sql.Timestamp)c.get("payment_deadline")).toInstant().isBefore(Instant.now()))throw new ConflictException("Current payment reservation is required");
        UUID intent=existing.isEmpty()?db.queryForObject("INSERT INTO clinic_payment_intents(id,invoice_id,provider) SELECT appointment_id,id,? FROM clinic_invoices WHERE appointment_id=? RETURNING id",UUID.class,provider().name(),id):(UUID)existing.getFirst().get("id");
        // Adapter create must deduplicate by intent UUID, including a process crash after its response.
        String ref=provider().create(new ClinicPaymentProvider.Intent(intent,number(c,"price_units"),"IRR",id));if(ref==null||ref.isBlank())throw new ConflictException("Provider did not return an intent reference");
        if(!existing.isEmpty()&&existing.getFirst().get("provider_reference")!=null&&!ref.equals(existing.getFirst().get("provider_reference")))throw new ConflictException("Provider intent reference changed; reconciliation required");
        db.update("UPDATE clinic_payment_intents SET provider_reference=?,state='PENDING',updated_at=CURRENT_TIMESTAMP WHERE id=? AND state IN('CREATED','PENDING','FAILED','TIMED_OUT')",ref,intent);return Map.of("intentId",intent,"state","PENDING","reference",ref);}
    public void reconcile(UUID actor,UUID id){enabled();finance(actor);reconcileCapture(actor,id);}
    public void callback(byte[] body,String signature){enabled();if(body==null||body.length>65536||signature==null||signature.isBlank()||signature.length()>4096)throw new ForbiddenException("A bounded authenticated provider callback is required");String ref;try{ref=provider().verifyCallback(body,signature);}catch(RuntimeException rejected){throw new ForbiddenException("Provider callback authentication failed");}var rows=db.queryForList("SELECT i.appointment_id FROM clinic_payment_intents p JOIN clinic_invoices i ON i.id=p.invoice_id WHERE p.provider=? AND p.provider_reference=?",provider().name(),ref);if(rows.isEmpty())throw new ConflictException("Callback reference is not an existing intent");reconcileCapture(null,(UUID)rows.getFirst().get("appointment_id"));}
    private void reconcileCapture(UUID actor,UUID id){var c=lock(id);providerGate((String)c.get("consultation_mode"));var rows=db.queryForList("SELECT p.* FROM clinic_payment_intents p JOIN clinic_invoices i ON i.id=p.invoice_id WHERE i.appointment_id=?",id);if(rows.isEmpty())throw new ConflictException("No payment intent exists");var intent=rows.getFirst();if(!provider().name().equals(intent.get("provider")))throw new ConflictException("Original payment adapter is required");String ref=(String)intent.get("provider_reference");if(ref==null)throw new ConflictException("Intent creation needs recovery");var e=provider().reconcile(ref);validateEvidence(e,ref,"CAPTURE",number(c,"price_units"));UUID evidence=evidence(e);if(captured(id))return;
        db.update("UPDATE clinic_payment_intents SET state='CAPTURED',updated_at=CURRENT_TIMESTAMP WHERE id=?",intent.get("id"));ledger(id,"CAPTURE",number(c,"price_units"),evidence);
        boolean eligible;try{access.requireCare((UUID)c.get("requester_user_id"),(UUID)c.get("professional_user_id"),(String)c.get("consultation_mode"));eligible=Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM account_eligibility WHERE user_id=? AND residence_country='IR' AND(current_country IS NULL OR current_country='IR'))",Boolean.class,c.get("professional_user_id")));}catch(ForbiddenException denied){eligible=false;}
        if(eligible&&"PAYMENT_PENDING".equals(c.get("status"))&&((java.sql.Timestamp)c.get("payment_deadline")).toInstant().isAfter(Instant.now())){transition(c,actor,"CONFIRMED","Provider independently confirmed the exact charge");}
        else {transition(c,actor,"CANCELLED_BY_PLATFORM","Late captured charge; refund required, no service confirmation");obligation(c,"Late provider capture after reservation ended");}}
    private void validateEvidence(ClinicPaymentProvider.Evidence e,String reference,String kind,long amount){if(e==null||e.eventKey()==null||e.eventKey().isBlank()||!reference.equals(e.reference())||!kind.equals(e.kind())||amount!=e.units()||!"IRR".equals(e.currency()))throw new ConflictException("Provider evidence does not match the expected operation, reference, amount and currency");}
    private UUID evidence(ClinicPaymentProvider.Evidence e){var old=db.queryForList("SELECT * FROM clinic_provider_events WHERE provider=? AND event_key=?",provider().name(),e.eventKey());if(!old.isEmpty()){var r=old.getFirst();if(!e.reference().equals(r.get("reference"))||!e.kind().equals(r.get("kind"))||e.units()!=number(r,"amount_units"))throw new ConflictException("Provider event replay conflicts with original evidence");return(UUID)r.get("id");}return db.queryForObject("INSERT INTO clinic_provider_events(provider,event_key,reference,kind,amount_units,currency) VALUES(?,?,?,?,?,'IRR') RETURNING id",UUID.class,provider().name(),e.eventKey(),e.reference(),e.kind(),e.units());}
    private boolean captured(UUID id){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_financial_events WHERE appointment_id=? AND kind='CAPTURE')",Boolean.class,id));}
    private void ledger(UUID id,String kind,long amount,UUID evidence){db.update("INSERT INTO clinic_financial_events(appointment_id,kind,amount_units,currency,provider_event_id) VALUES(?,?,?,'IRR',?) ON CONFLICT(appointment_id,kind) DO NOTHING",id,kind,amount,evidence);}
    private void obligation(Map<String,Object> c,String reason){UUID id=(UUID)c.get("id");if(!captured(id))return;long amount=number(c,"price_units");db.update("INSERT INTO clinic_refunds(appointment_id,amount_units,state,reason) VALUES(?,?,'REFUND_ELIGIBLE',?) ON CONFLICT(appointment_id) DO NOTHING",id,amount,reason);ledger(id,"REFUND_OBLIGATION",amount,null);}
    public void dispute(UUID who,UUID id,String reason){authority.actor(who);var c=lock(id);if(!who.equals(c.get("requester_user_id")))throw new NotFoundException("Own appointment was not found");ProfessionalAuthority.text(reason,2000);db.update("INSERT INTO clinic_disputes(appointment_id,patient_id,reason) VALUES(?,?,?) ON CONFLICT(appointment_id) DO NOTHING",id,who,reason);}
    public void resolve(UUID actor,UUID id,boolean refund,String reason){finance(actor);var c=lock(id);ProfessionalAuthority.text(reason,2000);if(db.update("UPDATE clinic_disputes SET state='RESOLVED',resolution=?,resolved_by=? WHERE appointment_id=? AND state='OPEN'",reason,actor,id)!=1)throw new ConflictException("An open dispute is required");if(refund)obligation(c,reason);authority.audit(actor,"FINANCIAL_DISPUTE_RESOLVED",id,reason);}
    public void noShow(UUID actor,UUID id,String evidence,boolean outageReconciled){finance(actor);var c=lock(id);ProfessionalAuthority.text(evidence,2000);if("PROFESSIONAL_NO_SHOW".equals(c.get("status")))return;
        if(!outageReconciled||!"CONFIRMED".equals(c.get("status"))||((java.sql.Timestamp)c.get("scheduled_at")).toInstant().plusSeconds(600).isAfter(Instant.now()))throw new ConflictException("Reconciled technical evidence, confirmed service and elapsed grace period required");
        if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_readiness_evidence WHERE appointment_id=? AND actor_id=?) OR EXISTS(SELECT 1 FROM clinic_appointment_events WHERE appointment_id=? AND state IN('SESSION_ACTIVE','COMPLETED','TECHNICAL_FAILURE'))",Boolean.class,id,c.get("professional_user_id"),id)))throw new ConflictException("Attendance or service evidence requires individual review; missing heartbeat is insufficient");
        transition(c,actor,"PROFESSIONAL_NO_SHOW",evidence);obligation(c,evidence);db.update("INSERT INTO notifications(user_id,type,title,body) VALUES(?,'SYSTEM_NOTICE','Service update','Open My Payments for the service outcome, any refund amount and status, and the dispute route. Refund initiation has a 48-hour target; bank availability varies.')",c.get("requester_user_id"));}
    public void requestRefund(UUID actor,UUID id){enabled();finance(actor);var c=lock(id);providerGate((String)c.get("consultation_mode"));var rows=db.queryForList("SELECT * FROM clinic_refunds WHERE appointment_id=? FOR UPDATE",id);if(rows.isEmpty())throw new ConflictException("An eligible refund obligation is required");var r=rows.getFirst();if("REFUND_CONFIRMED".equals(r.get("state")))return;String capture=db.queryForObject("SELECT p.provider_reference FROM clinic_payment_intents p JOIN clinic_invoices i ON i.id=p.invoice_id WHERE i.appointment_id=? AND p.provider=? AND p.state='CAPTURED'",String.class,id,provider().name());
        String ref=provider().refund((UUID)r.get("id"),capture,number(r,"amount_units"),"IRR");if(ref==null||ref.isBlank())throw new ConflictException("Provider refund initiation needs retry or manual review");if(r.get("provider_reference")!=null&&!ref.equals(r.get("provider_reference")))throw new ConflictException("Refund reference changed; manual reconciliation required");db.update("UPDATE clinic_refunds SET state='REFUND_PROCESSING',provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",ref,r.get("id"));}
    public void reconcileRefund(UUID actor,UUID id){enabled();finance(actor);var c=lock(id);providerGate((String)c.get("consultation_mode"));var r=db.queryForList("SELECT * FROM clinic_refunds WHERE appointment_id=? FOR UPDATE",id);if(r.isEmpty()||r.getFirst().get("provider_reference")==null)throw new ConflictException("A provider refund reference is required");var refund=r.getFirst();String ref=(String)refund.get("provider_reference");var e=provider().reconcile(ref);validateEvidence(e,ref,"REFUND",number(refund,"amount_units"));UUID receipt=evidence(e);ledger(id,"REFUND_CONFIRMED",number(refund,"amount_units"),receipt);if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_financial_events WHERE appointment_id=? AND kind='PLATFORM_FEE')",Boolean.class,id)))ledger(id,"COMMISSION_REVERSAL",number(c,"commission_units"),receipt);if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_financial_events WHERE appointment_id=? AND kind='PROFESSIONAL_PAYABLE')",Boolean.class,id)))ledger(id,"PAYABLE_REVERSAL",number(c,"price_units")-number(c,"commission_units")-number(c,"provider_fee_units"),receipt);db.update("UPDATE clinic_refunds SET state='REFUND_CONFIRMED',updated_at=CURRENT_TIMESTAMP WHERE id=?",refund.get("id"));}
    public int expireReservations(UUID actor){finance(actor);int count=0;for(var row:db.queryForList("SELECT id FROM consultation_requests WHERE clinic_governed AND status IN('PAYMENT_PENDING','REQUESTED') AND payment_deadline<CURRENT_TIMESTAMP ORDER BY id LIMIT 100 FOR UPDATE SKIP LOCKED")){var c=lock((UUID)row.get("id"));transition(c,actor,"CANCELLED_BY_PLATFORM","Reservation expired without service/payment confirmation");db.update("UPDATE professional_availability_slots SET status='CANCELLED',revision=revision+1 WHERE id=?",c.get("availability_slot_id"));count++;}return count;}
    public Map<String,Object> finances(UUID who,boolean professional){authority.actor(who);if(professional)authority.owner(who);String owner=professional?"professional_user_id":"requester_user_id";var rows=db.queryForList("SELECT c.id,c.scheduled_at,c.status,c.price_units,c.commission_units,c.provider_fee_units,c.currency,i.id AS invoice_id,i.issued_at,p.state AS payment_state,CASE WHEN p.state='CAPTURED' THEN p.provider_reference END AS receipt_reference,(SELECT f.created_at FROM clinic_financial_events f WHERE f.appointment_id=c.id AND f.kind='CAPTURE') AS payment_confirmed_at,(SELECT f.created_at FROM clinic_financial_events f WHERE f.appointment_id=c.id AND f.kind='REFUND_CONFIRMED') AS refund_confirmed_at,r.amount_units AS refund_due_units,r.state AS refund_state,r.initiate_by,ledger.captured_units,ledger.earned_commission_units,ledger.earned_payable_units,ledger.reversed_payable_units,ledger.settled_units,EXISTS(SELECT 1 FROM clinic_disputes d WHERE d.appointment_id=c.id AND d.state='OPEN') AS dispute_open FROM consultation_requests c JOIN clinic_invoices i ON i.appointment_id=c.id LEFT JOIN clinic_payment_intents p ON p.invoice_id=i.id LEFT JOIN clinic_refunds r ON r.appointment_id=c.id LEFT JOIN LATERAL(SELECT COALESCE(max(amount_units) FILTER(WHERE kind='CAPTURE'),0) AS captured_units,COALESCE(max(amount_units) FILTER(WHERE kind='PLATFORM_FEE'),0) AS earned_commission_units,COALESCE(max(amount_units) FILTER(WHERE kind='PROFESSIONAL_PAYABLE'),0) AS earned_payable_units,COALESCE(max(amount_units) FILTER(WHERE kind='PAYABLE_REVERSAL'),0) AS reversed_payable_units,COALESCE(max(amount_units) FILTER(WHERE kind='SETTLEMENT_CONFIRMED'),0) AS settled_units FROM clinic_financial_events f WHERE f.appointment_id=c.id) ledger ON TRUE WHERE c.clinic_governed AND c."+owner+"=? ORDER BY c.scheduled_at DESC LIMIT 100",who);for(var r:rows){long due=Math.max(0,number(r,"earned_payable_units")-number(r,"reversed_payable_units")-number(r,"settled_units"));r.put("net_due_units",due);r.put("held_units",r.get("refund_state")!=null||Boolean.TRUE.equals(r.get("dispute_open"))?due:0L);}return Map.of("appointments",safe(rows),"subscriptions",professional?subscriptions(who):List.of(),"payoutProcessingEnabled",false,"currency","IRR","IRTDisplayDivisor",10,"notice","Recorded refund obligations are not spendable funds. Only provider-confirmed receipts establish payment/refund/settlement.");}
    public UUID plan(UUID actor,String version,List<String> entitlements,long units,int periodDays){roles.admin(actor);if(periodDays<1||periodDays>366||units<0||units>1000000000000L||entitlements==null||entitlements.isEmpty()||!Set.of("CALENDAR_TOOLS","ADMIN_REPORTS","PRACTICE_TOOLS","EDITORIAL_WORKSPACE").containsAll(entitlements))throw new IllegalArgumentException("Only nonclinical administrative plan entitlements are supported");return db.queryForObject("INSERT INTO clinic_subscription_plans(version,entitlements,price_units,currency,approved_by,period_days) VALUES(?,?,?,'IRR',?,?) RETURNING id",UUID.class,version,entitlements.toArray(String[]::new),units,actor,periodDays);}
    public List<Map<String,Object>> plans(UUID who){authority.owner(who);return safe(db.queryForList("SELECT id,version,entitlements,price_units,currency,period_days FROM clinic_subscription_plans WHERE period_days IS NOT NULL ORDER BY created_at DESC LIMIT 100"));}
    public Map<String,Object> subscribe(UUID who,UUID plan,UUID retry,boolean confirm){enabled();authority.owner(who);authority.lock(who);if(!confirm)throw new ConflictException("Explicit acceptance of the plan, period and price is required");
        var rows=db.queryForList("SELECT * FROM clinic_subscription_plans WHERE id=? AND period_days IS NOT NULL",plan);if(rows.isEmpty())throw new NotFoundException("Configured subscription plan was not found");var p=rows.getFirst();
        var old=db.queryForList("SELECT * FROM clinic_subscription_orders WHERE professional_id=? AND retry_key=? FOR UPDATE",who,retry);if(!old.isEmpty()&&!plan.equals(old.getFirst().get("plan_id")))throw new ConflictException("Retry key is bound to a different plan");
        UUID order=old.isEmpty()?db.queryForObject("INSERT INTO clinic_subscription_orders(id,professional_id,plan_id,retry_key) VALUES(?,?,?,?) RETURNING id",UUID.class,retry,who,plan,retry):(UUID)old.getFirst().get("id");
        if(number(p,"price_units")==0)activateSubscription(order,null);
        else {providerGate("TEXT");if(old.isEmpty()||!"ACTIVE".equals(old.getFirst().get("state"))){String ref=provider().subscription(order,number(p,"price_units"),"IRR");if(ref==null||ref.isBlank())throw new ConflictException("Subscription provider reference is required");db.update("UPDATE clinic_subscription_orders SET provider=?,provider_reference=? WHERE id=? AND(provider_reference IS NULL OR provider_reference=?)",provider().name(),ref,order,ref);}}
        return (Map<String,Object>)ProfessionalAuthority.jsonSafe(db.queryForMap("SELECT id,plan_id,state,provider_reference FROM clinic_subscription_orders WHERE id=?",order));}
    private void activateSubscription(UUID order,UUID evidence){db.update("INSERT INTO clinic_professional_subscriptions(professional_id,plan_id,starts_at,ends_at,provider_event_id,order_id) SELECT o.professional_id,o.plan_id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP+p.period_days*INTERVAL '1 day',?,o.id FROM clinic_subscription_orders o JOIN clinic_subscription_plans p ON p.id=o.plan_id WHERE o.id=? ON CONFLICT(order_id) DO NOTHING",evidence,order);db.update("UPDATE clinic_subscription_orders SET state='ACTIVE' WHERE id=?",order);}
    public void reconcileSubscription(UUID actor,UUID order){enabled();finance(actor);var rows=db.queryForList("SELECT o.*,p.price_units FROM clinic_subscription_orders o JOIN clinic_subscription_plans p ON p.id=o.plan_id WHERE o.id=? FOR UPDATE OF o",order);if(rows.isEmpty())throw new NotFoundException("Subscription order was not found");var o=rows.getFirst();if("ACTIVE".equals(o.get("state")))return;providerGate("TEXT");if(!provider().name().equals(o.get("provider"))||o.get("provider_reference")==null)throw new ConflictException("Original subscription payment reference required");var e=provider().reconcile((String)o.get("provider_reference"));validateEvidence(e,(String)o.get("provider_reference"),"CAPTURE",number(o,"price_units"));activateSubscription(order,evidence(e));}
    public List<Map<String,Object>> subscriptions(UUID who){authority.owner(who);return safe(db.queryForList("SELECT p.version,p.entitlements,p.price_units,p.currency,s.starts_at,s.ends_at FROM clinic_professional_subscriptions s JOIN clinic_subscription_plans p ON p.id=s.plan_id WHERE s.professional_id=? ORDER BY s.starts_at DESC LIMIT 100",who));}
    public void settle(UUID actor,UUID id){enabled();finance(actor);var c=lock(id);providerGate((String)c.get("consultation_mode"));
        if(!"COMPLETED".equals(c.get("status"))||!captured(id)||Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_refunds WHERE appointment_id=?) OR EXISTS(SELECT 1 FROM clinic_disputes WHERE appointment_id=? AND state='OPEN')",Boolean.class,id,id)))throw new ConflictException("Only completed, captured, unheld service is eligible for settlement");
        if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_release_approvals a JOIN users u ON u.id=a.approved_by JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE a.country_code='IR' AND a.mode=? AND a.purpose='SETTLEMENT' AND a.revoked_at IS NULL AND a.expires_at>CURRENT_TIMESTAMP AND u.status='ACTIVE' AND r.name='ADMIN')",Boolean.class,c.get("consultation_mode"))))throw new ForbiddenException("Independent banking/settlement approval is required");
        var payable=db.queryForList("SELECT amount_units FROM clinic_financial_events WHERE appointment_id=? AND kind='PROFESSIONAL_PAYABLE'",id);if(payable.isEmpty())throw new ConflictException("Earned professional payable evidence is required");long amount=number(payable.getFirst(),"amount_units");if(amount<=0)throw new ConflictException("No positive payable exists");
        UUID request=db.queryForObject("INSERT INTO clinic_settlement_requests(id,appointment_id,amount_units) VALUES(?,?,?) ON CONFLICT(appointment_id) DO UPDATE SET appointment_id=EXCLUDED.appointment_id RETURNING id",UUID.class,id,id,amount);var r=db.queryForMap("SELECT * FROM clinic_settlement_requests WHERE id=? FOR UPDATE",request);if("CONFIRMED".equals(r.get("state")))return;
        String ref=provider().settle(request,(UUID)c.get("professional_user_id"),amount,"IRR");if(ref==null||ref.isBlank()||r.get("provider_reference")!=null&&!ref.equals(r.get("provider_reference")))throw new ConflictException("Stable provider settlement reference required");db.update("UPDATE clinic_settlement_requests SET state='PROCESSING',provider_reference=? WHERE id=?",ref,request);}
    public void reconcileSettlement(UUID actor,UUID id){enabled();finance(actor);var c=lock(id);providerGate((String)c.get("consultation_mode"));var rows=db.queryForList("SELECT * FROM clinic_settlement_requests WHERE appointment_id=? FOR UPDATE",id);if(rows.isEmpty()||rows.getFirst().get("provider_reference")==null)throw new ConflictException("Provider settlement reference is required");var r=rows.getFirst();var e=provider().reconcile((String)r.get("provider_reference"));validateEvidence(e,(String)r.get("provider_reference"),"SETTLEMENT",number(r,"amount_units"));ledger(id,"SETTLEMENT_CONFIRMED",number(r,"amount_units"),evidence(e));db.update("UPDATE clinic_settlement_requests SET state='CONFIRMED' WHERE id=?",r.get("id"));}
    public Map<String,Object> operations(UUID actor){finance(actor);return Map.of("overdueRefunds",safe(db.queryForList("SELECT appointment_id,state,initiate_by FROM clinic_refunds WHERE state IN('REFUND_ELIGIBLE','REFUND_FAILED','MANUAL_REVIEW_REQUIRED') AND initiate_by<CURRENT_TIMESTAMP LIMIT 100")),"openDisputes",safe(db.queryForList("SELECT id,appointment_id,created_at FROM clinic_disputes WHERE state='OPEN' LIMIT 100")),"pendingPayments",db.queryForObject("SELECT count(*) FROM clinic_payment_intents WHERE state<>'CAPTURED'",Long.class));}
    public static long number(Map<String,Object> row,String key){return((Number)row.get(key)).longValue();}
    @SuppressWarnings("unchecked") private static List<Map<String,Object>> safe(List<Map<String,Object>> rows){return(List<Map<String,Object>>)ProfessionalAuthority.jsonSafe(rows);}
}
